    [TestMethod]
    public void FormatPhoneNumber_ValidDigits_ReturnsFormattedNumber()
    {
        var result = _formatter.FormatPhoneNumber("2125551234");

        Assert.AreEqual("(212) 555-1234", result);
        StringAssert.StartsWith(result, "(212)");
        StringAssert.EndsWith(result, "1234");
        StringAssert.Contains(result, "555");
    }

    [TestMethod]
    public void FormatPhoneNumber_AlwaysWrapsAreaCodeInParens()
    {
        var result = _formatter.FormatPhoneNumber("8005559876");

        StringAssert.StartsWith(result, "(");
        StringAssert.Contains(result, ") ");
        StringAssert.Matches(result, new(@"^\(\d{3}\) \d{3}-\d{4}$"));
    }

    [TestMethod]
    public void FormatPhoneNumber_Null_Throws()
    {
        Assert.ThrowsException<ArgumentNullException>(
            () => _formatter.FormatPhoneNumber(null!));
    }

    [TestMethod]
    [DataRow("123")]
    [DataRow("12345678901")]
    [DataRow("")]
    public void FormatPhoneNumber_WrongLength_Throws(string digits)
    {
        Assert.ThrowsException<ArgumentException>(
            () => _formatter.FormatPhoneNumber(digits));
    }

    // ── BuildGreeting ──────────────────────────────────────────────

    [TestMethod]
    public void BuildGreeting_DefaultTitle_StartsDearMr()
    {
        var result = _formatter.BuildGreeting("Smith");

        Assert.AreEqual("Dear Mr. Smith,", result);
        StringAssert.StartsWith(result, "Dear Mr.");
        StringAssert.EndsWith(result, ",");
    }

    [TestMethod]
    public void BuildGreeting_CustomTitle_UsesTitle()
    {
        var result = _formatter.BuildGreeting("Johnson", "Dr.");

        StringAssert.StartsWith(result, "Dear Dr.");
        StringAssert.EndsWith(result, "Johnson,");
    }

    [TestMethod]
    public void BuildGreeting_AlwaysEndsWithComma()
    {
        var result = _formatter.BuildGreeting("Doe", "Ms.");

        StringAssert.EndsWith(result, ",");
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void BuildGreeting_NullOrWhitespaceName_Throws(string? name)
    {
        Assert.ThrowsException<ArgumentException>(
            () => _formatter.BuildGreeting(name!));
    }

    // ── GenerateSlug ───────────────────────────────────────────────

    [TestMethod]
    public void GenerateSlug_SimpleTitle_ReturnsLowercaseHyphenated()
    {
        var result = _formatter.GenerateSlug("Hello World");

        Assert.AreEqual("hello-world", result);
        StringAssert.Matches(result, new(@"^[a-z0-9-]+$"));
    }

    [TestMethod]
    public void GenerateSlug_SpecialCharacters_StripsAndHyphenates()
    {
        var result = _formatter.GenerateSlug("C# is Great!!!");

        StringAssert.StartsWith(result, "c-");
        StringAssert.EndsWith(result, "great");
    }

    [TestMethod]
    public void GenerateSlug_LeadingTrailingSpaces_Trimmed()
    {
        var result = _formatter.GenerateSlug("  My Post  ");

        Assert.AreEqual("my-post", result);
    }

    [TestMethod]
    public void GenerateSlug_NoLeadingOrTrailingHyphens()
    {
        var result = _formatter.GenerateSlug("---Hello---");

        Assert.IsFalse(result.StartsWith('-'));
        Assert.IsFalse(result.EndsWith('-'));
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void GenerateSlug_NullOrWhitespace_Throws(string? title)
    {
        Assert.ThrowsException<ArgumentException>(
            () => _formatter.GenerateSlug(title!));
    }

    // ── FormatCurrency ─────────────────────────────────────────────

    [TestMethod]
    public void FormatCurrency_DefaultSymbol_StartsDollarSign()
    {
        var result = _formatter.FormatCurrency(9.99m);

        StringAssert.StartsWith(result, "$");
        Assert.AreEqual("$9.99", result);
    }

    [TestMethod]
    public void FormatCurrency_CustomSymbol_UsesSymbol()
    {
        var result = _formatter.FormatCurrency(19.99m, "€");

        StringAssert.StartsWith(result, "€");
        StringAssert.EndsWith(result, "19.99");
    }

    [TestMethod]
    public void FormatCurrency_WholeNumber_ShowsTwoDecimals()
    {
        var result = _formatter.FormatCurrency(100m);

        StringAssert.EndsWith(result, ".00");
    }

    [TestMethod]
    public void FormatCurrency_NegativeAmount_FormatsCorrectly()
    {
        var result = _formatter.FormatCurrency(-5.50m);

        StringAssert.Contains(result, "-");
        StringAssert.EndsWith(result, "5.50");
    }

    [TestMethod]
    public void FormatCurrency_Zero_ReturnsSymbolAndZero()
    {
        var result = _formatter.FormatCurrency(0m, "£");

        Assert.AreEqual("£0.00", result);
        StringAssert.StartsWith(result, "£");
    }
}

